CREATE TABLE t1(id INTEGER PRIMARY KEY, a, b, c); CREATE INDEX i1 ON t1(a); CREATE INDEX i2 ON t1(b); CREATE INDEX i3 ON t1(c); WITH RECURSIVE seq(n) AS (VALUES(1) UNION ALL SELECT n + 1 FROM seq WHERE n < 30000) INSERT OR IGNORE INTO t1(id, a, b, c) SELECT CASE WHEN n % 4096 = 0 THEN ((n - 1) * 654435761) % 1000000000 ELSE (n * 654435761) % 1000000000 END, 'a', 'b', 'c' FROM seq;